func fdtPar(nodes *port.Cells, regions *port.Cells, text *port.Cells, b []byte, x0 int32, y0 int32, x1 int32, y1 int32) int32 {
	// A paragraph under the document, with this text and this box on page 1.
	var n int32 = model.NodeNew(nodes, model.NkParagraph(), 0)
	var s int32 = model.TextLen(text)
	model.TextAppendUtf8(text, b, 0, port.BlobLen(b))
	model.NodeSetText(nodes, n, s, model.TextLen(text)-s)
	model.NodeAddRegion(nodes, regions, n, 1, x0, y0, x1, y1)
	return n
}

func fdtRun(txt *port.Cells, b []byte) int32 {
	// Append b to the annotation text and answer where it starts.
	var s int32 = port.CellsLen(txt)
	model.TextAppendUtf8(txt, b, 0, port.BlobLen(b))
	return s
}

func fdtField(an *port.Cells, txt *port.Cells, kind int32, checked int32, name []byte, value []byte, export []byte, x0 int32, y0 int32, x1 int32, y1 int32) int32 {
	// One `an-field` row (the layout is in the head of `emon.pdfannot`) on page 1: kind 2 check box, 3 radio, 4 text; `checked` for a button; the strings may be empty.
	var at int32 = port.CellsLen(an)
	var ns int32 = fdtRun(txt, name)
	var vs int32 = fdtRun(txt, value)
	var es int32 = fdtRun(txt, export)
	var k int32 = 0
	for k < 38 {
		port.CellsPush(an, 0)
		k += 1
	}
	port.CellsSet(an, at+1, pdfannot.AnField())
	port.CellsSet(an, at+4, x0)
	port.CellsSet(an, at+5, y0)
	port.CellsSet(an, at+6, x1)
	port.CellsSet(an, at+7, y1)
	port.CellsSet(an, at+8, kind)
	port.CellsSet(an, at+9, checked)
	port.CellsSet(an, at+11, 1)
	port.CellsSet(an, at+12, ns)
	port.CellsSet(an, at+13, port.BlobLen(name))
	port.CellsSet(an, at+14, -1)
	port.CellsSet(an, at+16, -1)
	port.CellsSet(an, at+18, -1)
	if port.BlobLen(value) > 0 {
		port.CellsSet(an, at+14, vs)
		port.CellsSet(an, at+15, port.BlobLen(value))
	}
	if port.BlobLen(export) > 0 {
		port.CellsSet(an, at+16, es)
		port.CellsSet(an, at+17, port.BlobLen(export))
	}
	return 0
}

