func TestTheW9sEightBoxesAndFifteenTextFieldsLandBesideTheirLabels(emonT *testing.T) {
	// The W-9's first page: each of the seven boxes of 3a is before the label to its right (the first is on, so it says so and its value is the export value), the
	// LLC box before the LLC line and the letter box after it (the label above it is nearer by 4 pt, the one to its left by 7.6: the left one stays), `Other` and its box,
	// the box of 3b after the line it ends (the dot leaders join them), the name field after the name label (it has a value), the address, the requester, the city, the account
	// number after their labels above them, the three boxes of the number after `Social security number` and the two of the EIN after theirs; and no field is left over.
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var an *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var out *strings.Builder = port.NewText()
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	fdtW9Text(nodes, regions, text)
	fdtW9Fields(an, txt)
	fdtHtml(emonT, nodes, attrs, regions, text, an, txt, out)
	port.AssertText(emonT, out, "<!doctype html><html><head><meta charset=\"utf-8\"><title></title></head><body><main><p>1 Name of entity/individual. An entry is required.<span data-emon=\"field\" data-emon-name=\"f1_01[0]\" data-emon-type=\"text\">Ada Lovelace</span></p><p>2 Business name/disregarded entity name, if different from above.<span data-emon=\"field\" data-emon-name=\"f1_02[0]\" data-emon-type=\"text\"></span></p><p>3a Check the appropriate box for federal tax classification</p><p>4 Exemptions (codes apply only to</p><p><span data-emon=\"field\" data-emon-name=\"c1_1[0]\" data-emon-type=\"checkbox\" role=\"checkbox\" data-emon-checked=\"true\" aria-checked=\"true\" data-emon-value=\"1\"></span>Individual/sole proprietor</p><p><span data-emon=\"field\" data-emon-name=\"c1_1[1]\" data-emon-type=\"checkbox\" role=\"checkbox\" data-emon-checked=\"false\" aria-checked=\"false\" data-emon-value=\"2\"></span>C corporation</p><p><span data-emon=\"field\" data-emon-name=\"c1_1[2]\" data-emon-type=\"checkbox\" role=\"checkbox\" data-emon-checked=\"false\" aria-checked=\"false\" data-emon-value=\"3\"></span>S corporation</p><p><span data-emon=\"field\" data-emon-name=\"c1_1[3]\" data-emon-type=\"checkbox\" role=\"checkbox\" data-emon-checked=\"false\" aria-checked=\"false\" data-emon-value=\"4\"></span>Partnership</p><p><span data-emon=\"field\" data-emon-name=\"c1_1[4]\" data-emon-type=\"checkbox\" role=\"checkbox\" data-emon-checked=\"false\" aria-checked=\"false\" data-emon-value=\"5\"></span>Trust/estate</p><p>Exempt payee code (if any)<span data-emon=\"field\" data-emon-name=\"f1_05[0]\" data-emon-type=\"text\"></span></p><p><span data-emon=\"field\" data-emon-name=\"c1_1[5]\" data-emon-type=\"checkbox\" role=\"checkbox\" data-emon-checked=\"false\" aria-checked=\"false\" data-emon-value=\"6\"></span>LLC. Enter the tax classification (C = C corporation, S = S corporation, P = Partnership)<span data-emon=\"field\" data-emon-name=\"f1_03[0]\" data-emon-type=\"text\"></span></p><p>code (if any)<span data-emon=\"field\" data-emon-name=\"f1_06[0]\" data-emon-type=\"text\"></span></p><p><span data-emon=\"field\" data-emon-name=\"c1_1[6]\" data-emon-type=\"checkbox\" role=\"checkbox\" data-emon-checked=\"false\" aria-checked=\"false\" data-emon-value=\"7\"></span>Other (see instructions)<span data-emon=\"field\" data-emon-name=\"f1_04[0]\" data-emon-type=\"text\"></span></p><p>3b If on line 3a you checked Partnership or Trust/estate</p><p>this box if you have any foreign partners, owners, or beneficiaries. See instructions<span data-emon=\"field\" data-emon-name=\"c1_2[0]\" data-emon-type=\"checkbox\" role=\"checkbox\" data-emon-checked=\"false\" aria-checked=\"false\" data-emon-value=\"8\"></span></p><p>. . . .</p><p>5 Address (number, street, and apt. or suite no.). See instructions.<span data-emon=\"field\" data-emon-name=\"f1_07[0]\" data-emon-type=\"text\"></span></p><p>Requester's name and address (optional)<span data-emon=\"field\" data-emon-name=\"f1_09[0]\" data-emon-type=\"text\"></span></p><p>6 City, state, and ZIP code<span data-emon=\"field\" data-emon-name=\"f1_08[0]\" data-emon-type=\"text\"></span></p><p>7 List account number(s) here (optional)<span data-emon=\"field\" data-emon-name=\"f1_10[0]\" data-emon-type=\"text\"></span></p><p>Social security number<span data-emon=\"field\" data-emon-name=\"f1_11[0]\" data-emon-type=\"text\"></span><span data-emon=\"field\" data-emon-name=\"f1_12[0]\" data-emon-type=\"text\"></span><span data-emon=\"field\" data-emon-name=\"f1_13[0]\" data-emon-type=\"text\"></span></p><p>Enter your TIN in the appropriate box.</p><p>-</p><p>-</p><p>Employer identification number<span data-emon=\"field\" data-emon-name=\"f1_14[0]\" data-emon-type=\"text\"></span><span data-emon=\"field\" data-emon-name=\"f1_15[0]\" data-emon-type=\"text\"></span></p></main></body></html>", "the W-9's fields")
}

func TestTheJsonOfAFieldIsAnInlineWithItsWidgetsBox(emonT *testing.T) {
	// In the Model's JSON a field is an inline of its block, with no id: its name, type, value, whether it is on, the widget's box, `annot` and how far it is trusted; the block's text is
	// unchanged and its words are now a `text` inline beside the field.
	var nodes *port.Cells = port.NewCells()
	var attrs *port.Cells = port.NewCells()
	var regions *port.Cells = port.NewCells()
	var text *port.Cells = port.NewCells()
	var pages *port.Cells = port.NewCells()
	var ledger *port.Cells = port.NewCells()
	var layout *port.Cells = port.NewCells()
	var an *port.Cells = port.NewCells()
	var txt *port.Cells = port.NewCells()
	var nn *port.Cells = port.NewCells()
	var na *port.Cells = port.NewCells()
	var nr *port.Cells = port.NewCells()
	var nm *port.Cells = port.NewCells()
	var fc *port.Cells = port.NewCells()
	var fh *port.Cells = port.NewCells()
	var bt *port.Cells = port.NewCells()
	var sc *port.Cells = port.NewCells()
	var out *strings.Builder = port.NewText()
	model.ModelInit(nodes, attrs, regions, text, pages, ledger, layout)
	fdtPar(nodes, regions, text, port.TextBlob("Agree"), 8700, 18000, 16400, 18800)
	fdtField(an, txt, 2, 1, port.TextBlob("agree"), port.TextBlob(""), port.TextBlob("Yes"), 7300, 18020, 8100, 18820)
	port.AssertEq(emonT, fields.FlRun(nodes, attrs, regions, text, nn, na, nr, nm, an, txt, fc, fh, bt, sc), 4, "put in: the document, the paragraph, the field and its text")
	json.JsEmit(out, 0, nn, na, nr, text, pages, ledger, layout, port.NewCells(), port.NewCells())
	port.AssertText(emonT, out, "{\"emon\":\"1.1\",\"settings\":{\"locale\":null},\"conf\":\"calibrated\",\"pages\":[],\"body\":{\"id\":0,\"kind\":\"document\",\"children\":[{\"id\":1,\"kind\":\"paragraph\",\"text\":\"Agree\",\"inlines\":[{\"kind\":\"field\",\"name\":\"agree\",\"type\":\"checkbox\",\"value\":\"Yes\",\"checked\":true,\"at\":[[1,73,180.2,81,188.2]],\"src\":[\"annot\"],\"conf\":950},{\"kind\":\"text\",\"text\":\"Agree\",\"src\":[\"text\"],\"conf\":815}],\"at\":[[1,87,180,164,188]]}]},\"furniture\":[],\"dropped\":[]}", "the JSON")
}
